 // Form interactivity for consent checkbox
 (function() {
   const form = document.getElementById('consent-form');
   const checkbox = document.getElementById('agree-terms');
   const errorMessage = document.getElementById('agree-error');
   const successMessage = document.getElementById('success-message');

   function clearError() {
     errorMessage.hidden = true;
     checkbox.setAttribute('aria-invalid', 'false');
   }

   checkbox.addEventListener('change', () => {
     if (checkbox.checked) {
       clearError();
     }
   });

   form.addEventListener('submit', (e) => {
     e.preventDefault();

     if (!checkbox.checked) {
       errorMessage.textContent = 'Error: You must agree to the terms to continue.';
       errorMessage.hidden = false;
       checkbox.setAttribute('aria-invalid', 'true');
       checkbox.focus();
       return;
     }

     clearError();
     successMessage.hidden = false;

     setTimeout(() => {
       successMessage.hidden = true;
       checkbox.checked = false;
       checkbox.setAttribute('aria-invalid', 'false');
     }, 3000);
   });
 })();

