  line-height: 1.6;
}

body {
  background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

#root {
  width: 100%;
  max-width: 500px;
}

.form-container {
  background: white;
  border-radius: 12px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);
  padding: 40px;
}

h1 {
  font-size: 28px;
  font-weight: 600;
  margin-bottom: 12px;
  line-height: 1.2;
}

.subtitle {
  font-size: 16px;
  color: #666;
  margin-bottom: 32px;
}

form {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.form-field {
  display: flex;
  align-items: flex-start;
  gap: 12px;
}

.checkbox-content {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

/* Checkbox styling */
input[type="checkbox"] {
  width: 20px;
  height: 20px;
  min-width: 20px;
  margin-top: 2px;
  cursor: pointer;
  accent-color: #0066cc;
  flex-shrink: 0;
}

input[type="checkbox"]:focus-visible {
  outline: 3px solid #0066cc;
  outline-offset: 2px;
  border-radius: 4px;
}

input[type="checkbox"]:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

label {
  cursor: pointer;
  font-size: 16px;
  font-weight: 500;
  display: block;
  line-height: 1.5;
}

label a {
  color: #0066cc;
  text-decoration: underline;
  font-weight: 500;
}

label a:hover {
  color: #0052a3;
}

label a:focus-visible {
  outline: 3px solid #0066cc;
  outline-offset: 2px;
}

.required {
  color: #d32f2f;
  font-weight: bold;
  margin-left: 4px;
}

.helper-text {
  font-size: 14px;
  color: #666;
  margin: 0;
  line-height: 1.4;
}

.error-text {
  font-size: 14px;
  color: #d32f2f;
  margin: 0;
  line-height: 1.4;
  display: none;
}

.error-text.show {
  display: block;
}

button[type="submit"] {
  background-color: #0066cc;
  color: white;
  font-size: 16px;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  min-height: 44px;
  min-width: 44px;
}

button[type="submit"]:hover {
  background-color: #0052a3;
  box-shadow: 0 4px 12px rgba(0, 102, 204, 0.3);
}

button[type="submit"]:active {
  background-color: #003d7a;
  transform: scale(0.98);
}

button[type="submit"]:focus-visible {
  outline: 3px solid #0066cc;
  outline-offset: 2px;
}

button[type="submit"]:disabled {
  background-color: #ccc;
  cursor: not-allowed;
  opacity: 0.6;
}



/* Ensure adequate touch target size (WCAG 2.5.5) */
@media (max-width: 600px) {
  main {
    padding: 24px;
  }

  h1 {
    font-size: 24px;
  }

  button[type="submit"] {
    width: 100%;
  }
}

/* High contrast mode support */
@media (prefers-contrast: more) {
  input[type="checkbox"]:focus-visible {
    outline-width: 4px;
  }

  button[type="submit"]:focus-visible {
    outline-width: 4px;
  }

  h1 {
    font-weight: 700;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Forced colors mode support */
@media (forced-colors: active) {
  input[type="checkbox"] {
    forced-color-adjust: none;
  }

  button[type="submit"] {
    forced-color-adjust: none;
  }
}
