 // React-style component for consent form
 function ConsentForm() {
   return `
     <div class="form-container">
       <h1>Terms of Use</h1>
       <p class="subtitle">Please review and agree to our terms before proceeding.</p>

       <form id="consent-form" novalidate>
         <div class="form-field">
           <input
             id="agree-terms"
             type="checkbox"
             name="agree-terms"
             required
             aria-required="true"
             aria-describedby="agree-help agree-error"
           />
           <div class="checkbox-content">
             <label for="agree-terms">
               I agree to the <a href="#terms" target="_blank">terms of use</a> <span class="required" aria-hidden="true">*</span>
             </label>
             <p id="agree-help" class="helper-text">
               You must agree to our terms to continue using our service.
             </p>
             <p id="agree-error" class="error-text" hidden>
               Error: You must agree to the terms of use to proceed.
             </p>
           </div>
         </div>

         <button type="submit">Accept & Continue</button>
       </form>
     </div>
   `;
 }

 // Mount the component to the DOM
 function renderApp() {
   const root = document.getElementById('root');
   root.innerHTML = ConsentForm();
   attachEventListeners();
 }

 // Attach event listeners
 function attachEventListeners() {
   const form = document.getElementById('consent-form');
   const checkbox = document.getElementById('agree-terms');
   const errorText = document.getElementById('agree-error');

   checkbox.addEventListener('change', () => {
     if (checkbox.checked) {
       checkbox.setAttribute('aria-invalid', 'false');
       errorText.classList.remove('show');
     }
   });

   form.addEventListener('submit', (e) => {
     e.preventDefault();

     if (!checkbox.checked) {
       checkbox.setAttribute('aria-invalid', 'true');
       errorText.classList.add('show');
       checkbox.focus();
       return;
     }

     checkbox.setAttribute('aria-invalid', 'false');
     errorText.classList.remove('show');

     alert('Thank you for agreeing to the terms of use!');
   });
 }

 document.addEventListener('DOMContentLoaded', renderApp);

